-- Entries: positive = debit, negative = credit. Account key: 01 clearing(Acme), 02 clearing(Globex),
-- 11/12 Ada avail/reserved, 21/22 Grace avail/reserved, 31 Blue Bottle avail, 41 Northwind avail,
-- 111/112 Hedy avail/reserved, 121 Initech avail.
INSERT INTO ledger_entry (id, ledger_transaction_id, organization_id, ledger_account_id, amount_minor, currency, created_at)
SELECT v.id::uuid, t.id, t.organization_id, ('40000000-0000-4000-8000-' || lpad(v.account, 12, '0'))::uuid,
       v.amount, 'USD', t.posted_at
  FROM (VALUES
