    ('71000000-0000-4000-8000-000000000013', 7,  '41',     5000),
    ('71000000-0000-4000-8000-000000000014', 7,  '11',    -5000),
    ('71000000-0000-4000-8000-000000000015', 8,  '21',     8000),
    ('71000000-0000-4000-8000-000000000016', 8,  '22',    -8000),
    ('71000000-0000-4000-8000-000000000017', 9,  '21',    40000),
    ('71000000-0000-4000-8000-000000000018', 9,  '22',   -40000),
    ('71000000-0000-4000-8000-000000000019', 10, '22',    40000),
    ('71000000-0000-4000-8000-000000000020', 10, '41',   -40000),
    ('71000000-0000-4000-8000-000000000021', 11, '41',    40000),
    ('71000000-0000-4000-8000-000000000022', 11, '21',   -40000),
    ('71000000-0000-4000-8000-000000000023', 12, '11',    15000),
    ('71000000-0000-4000-8000-000000000024', 12, '12',   -15000),
    ('71000000-0000-4000-8000-000000000025', 13, '12',    15000),
