INSERT INTO payment_event (id, payment_id, organization_id, event_type, amount_minor, from_status, to_status,
                           ledger_transaction_id, actor_user_id, note, created_at)
SELECT v.id::uuid, ('60000000-0000-4000-8000-' || lpad(v.payment::text, 12, '0'))::uuid, p.organization_id,
       v.event_type, v.amount, v.from_status, v.to_status,
       CASE WHEN v.tx IS NULL THEN NULL ELSE ('70000000-0000-4000-8000-' || lpad(v.tx::text, 12, '0'))::uuid END,
       p.created_by, v.note, v.created_at::timestamptz
